1869: function Get-ReplNormalizedActionsBlock {
1870:     # Returns bare list content under the 'actions:' key (common indent stripped).
1871:     # Twin of _repl_normalized_actions_block + _repl_list_block_get.
1872:     # Safe for map-style turn docs (preserves nesting) and top-level actions: lists.
1873:     param([string]$ParamsYaml)
1874:     if (-not $ParamsYaml) { return '' }
1875:     $text = $ParamsYaml -replace "`r`n", "`n" -replace "`r", ""
1876:     $lines = $text -split "`n"
1877:     $capture = $false
1878:     $keyIndent = -1
1879:     $stripIndent = -1
1880:     $result = @()
1881:     foreach ($line in $lines) {
1882:         if (-not $capture) {
1883:             if ($line -match '^\s*actions:\s*$') {
1884:                 $capture = $true
1885:                 $m = [regex]::Match($line, '^(\s*)')
1886:                 $keyIndent = $m.Groups[1].Value.Length
1887:                 continue
1888:             }
1889:             continue
1890:         }
1891:         if ($line -match '^\s*$') {
1892:             $result += $line
1893:             continue
1894:         }
1895:         $m = [regex]::Match($line, '^(\s*)')
1896:         $lineIndent = $m.Groups[1].Value.Length
1897:         if ($lineIndent -le $keyIndent -and $line -notmatch '^\s*-') {
1898:             break
1899:         }
1900:         if ($stripIndent -lt 0) { $stripIndent = $lineIndent }
1901:         if ($stripIndent -gt 0 -and $line.Length -ge $stripIndent) {
1902:             $result += $line.Substring($stripIndent)
1903:         } else {
1904:             $result += $line
1905:         }
1906:     }
1907:     return ($result -join "`n").TrimEnd()
1908: }
