299: 711:     <#
300: 712:     .SYNOPSIS
301: 713:         Close stdin, kill the child process tree, and await owned pipe closure.
302: 714:     .DESCRIPTION
303: 715:         Process.WaitForExit waits only for the root process after Kill(true). Redirected stdout
304: 716:         and stderr remain open while a killed descendant is still exiting, so require those
305: 717:         drain tasks to complete inside the same cleanup reserve before confirming termination.
306: 718:     #>
307: 719:     param(
308: 720:         $Process,
309: 721:         $StdoutTask,
310: 722:         $StderrTask,
311: 723:         [int]$WaitMs = 500
312: 724:     )
313: 725: 
314: 726:     if ($null -eq $Process) { return $true }
315: 727:     try {
316: 728:         $Process.StandardInput.BaseStream.Dispose()
317: 729:     } catch {
318: 730:     }
319: 731:     try {
320: 732:         $Process.StandardInput.Dispose()
321: 733:     } catch {
322: 734:     }
323: 735:     try {
324: 736:         if (-not $Process.HasExited) {
325: 737:             $Process.Kill($true)
326: 738:         }
327: 739:     } catch {
328: 740:     }
329: 741: 
330: 742:     $cleanup = [System.Diagnostics.Stopwatch]::StartNew()
331: 743:     do {
332: 744:         $rootExited = $false
333: 745:         try { $rootExited = $Process.HasExited } catch { $rootExited = $true }
334: 746:         $stdoutClosed = -not $StdoutTask -or $StdoutTask.IsCompleted
335: 747:         $stderrClosed = -not $StderrTask -or $StderrTask.IsCompleted
336: 748:         if ($rootExited -and $stdoutClosed -and $stderrClosed) {
337: 749:             return $true
338: 750:         }
339: 751:         Start-Sleep -Milliseconds 10
340: 752:     } while ($cleanup.ElapsedMilliseconds -lt $WaitMs)
341: 753: 
342: 754:     return $false
343: 755: }
